import{_ as t,o as a,c as s,a2 as n}from"./chunks/framework.BAQ5ZYJQ.js";const g=JSON.parse('{"title":"What is running","description":"","frontmatter":{},"headers":[],"relativePath":"guide/status.md","filePath":"guide/status.md","lastUpdated":1795072660000}'),i={name:"guide/status.md"};function o(r,e,h,d,c,l){return a(),s("div",null,[...e[0]||(e[0]=[n(`<h1 id="what-is-running" tabindex="-1">What is running <a class="header-anchor" href="#what-is-running" aria-label="Permalink to &quot;What is running&quot;">​</a></h1><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # this project in full, one line per other project</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # every project in full</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>running   ( on mac, lmo: this machine, and every machine work was sent to from it )</span></span>
<span class="line"><span>  sdot-ffi</span></span>
<span class="line"><span>    lmo          3f2a9c1e  run tests/test_w2.py::*  --env lin  12 min  running</span></span>
<span class="line"><span>    jz           7c01d2aa  run train.py  --env jz            2 min   waiting: slurm job 81234 pending, 2 min</span></span>
<span class="line"><span>  guitar_2000: 2 running on lmo</span></span>
<span class="line"><span>  lmo: windows vm 80103674 ready, 8 cpus 16G</span></span></code></pre></div><p>One command answers the question you otherwise answer with an ssh per machine, a <code>ps</code>, a <code>squeue</code> and a guess: <strong>what did I start, where, and is it still there?</strong></p><h2 id="what-it-shows" tabindex="-1">What it shows <a class="header-anchor" href="#what-it-shows" aria-label="Permalink to &quot;What it shows&quot;">​</a></h2><ul><li><strong>Runs</strong>, wherever they are: here, over ssh, in an allocation, in a container, in a Windows guest.</li><li><strong>Where a run is</strong>, when it says so with <a href="./steps"><code>errand.step</code></a>: <code>running · iteration 41 · ▕████▏ ▏ 41 %</code>.</li><li><strong>What waits</strong> for something that is not there yet, in place of <code>running</code>: <code>waiting: slurm job 81234 pending, 2 h 10</code>, <code>waiting: room on lmo: gpus (0 free of 2, needs 1)</code>, <code>waiting: windows vm 80103674 booting</code>.</li><li><strong>What is kept warm</strong>: an allocation held between commands, a Windows VM, environment agents and processes with torch already imported (<code>Preload</code>). Agents and zygotes are counted on one line; <code>--all</code> lists them.</li><li><strong>Orphans</strong>: a process whose agent died. The next agent on that machine stops it.</li><li><strong>Unowned</strong> processes (Linux): something errand started that no record holds any more, an older errand&#39;s for instance. It is shown with the <code>kill</code> that stops it.</li><li><strong>Commands whose connection was lost</strong>: still running, or finished and waiting for <a href="./detached#close-the-laptop"><code>errand attach</code></a> to bring the results back.</li><li><strong><code>--batch</code> submissions</strong>, and how they are doing. → <a href="./detached">Let it run</a></li></ul><p>A machine that cannot be reached is listed as <code>cannot say</code>, with the reason, not silently skipped.</p><h2 id="how-it-knows" tabindex="-1">How it knows <a class="header-anchor" href="#how-it-knows" aria-label="Permalink to &quot;How it knows&quot;">​</a></h2><p>Every machine errand runs work on has an <a href="./agents">agent</a>. The agent writes down each process it starts, in its own directory, on that machine: the process group, its start time, the project.</p><p><code>errand status</code> reads those records. It reads this machine directly, and every machine work was sent to from here over one ssh each. The list of those machines is the <strong>ledger</strong>, <code>~/.cache/errand/ledger/</code>, which keeps a machine for two weeks after its last use. Nothing is started to answer: no agent, no allocation, no VM.</p><p>A Slurm allocation kept warm runs its agents on a compute node, where the login node can read neither their locks nor their processes. So for each allocation whose job runs, <code>errand status</code> asks its first node the same question, with <code>srun --overlap</code> inside the job: nothing new is asked of Slurm. Its rows show as <code>login &gt; node</code>.</p><p>Typed on a machine that runs work (a lab server, say), <code>errand status</code> shows everything its agents run, whoever started it and from wherever.</p><h3 id="the-machines-asked" tabindex="-1">The machines asked <a class="header-anchor" href="#the-machines-asked" aria-label="Permalink to &quot;The machines asked&quot;">​</a></h3><p>The machines are those work was sent to from here: errand keeps them, and forgets one after two weeks without work sent there. Looking at a machine ( <code>errand status</code>, <code>errand tui</code> ) does not keep it.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> machines</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">                       # which, most recently used first</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> machines</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> forget</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> h</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # not asked any more, until work is sent there again</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> machines</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rename</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cinaps</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lab</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">     # shown as \`lab\`, whatever name reaches it</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">errand</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> machines</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> watch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jz</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> off</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # never contacted ( on: always; auto: while work is sent there )</span></span></code></pre></div><p>A machine reached under several names ( <code>cinaps</code> and <code>hugo.leclerc@cinaps</code> ) is one: the same ssh name but for the user, the same label, or the same hostname answered. It shows its oldest name, or the label it was given.</p><p>A machine no work was sent to for a day is <strong>dormant</strong>: neither <code>errand status</code> nor <code>errand tui</code> contacts it, so that no agent of errand&#39;s starts for nothing on a machine others share ( a cluster&#39;s login node ). <code>errand status</code> names it; <code>errand tui</code> shows it greyed. <code>a</code> on a machine in <code>errand tui</code> switches watching it on or off, and it is saved: the next screen and <code>errand status</code> do the same. Sending work to a machine switched off watches it again.</p><p>In <code>errand tui</code>: <code>f</code> forgets the machine under the cursor, <code>r</code> names it, <code>k</code> kills what runs there, each once confirmed. Forgetting a machine stops nothing over there: <code>k</code>, or <code>errand agents stop</code>, does.</p><h2 id="stopping-work" tabindex="-1">Stopping work <a class="header-anchor" href="#stopping-work" aria-label="Permalink to &quot;Stopping work&quot;">​</a></h2><table tabindex="0"><thead><tr><th>what</th><th>how</th></tr></thead><tbody><tr><td>the command in front of you</td><td><strong>Ctrl-C</strong>. It reaches the work through every layer</td></tr><tr><td>everything kept warm</td><td><code>errand agents stop</code></td></tr><tr><td>what matches a name</td><td><code>errand agents stop gpu</code></td></tr><tr><td>an agent that still runs something</td><td><code>errand agents stop --force</code></td></tr><tr><td>Windows VMs, here and over every <code>Ssh</code></td><td><code>errand vm stop</code></td></tr><tr><td>a <code>--batch</code> submission</td><td>see <a href="./detached">Let it run</a></td></tr></tbody></table><p>Ctrl-C is handled by the agent over there, not by the errand in front of you: an interrupt first, a terminate after 2 s, a kill after 5 s, on the whole process group. It happens even if your laptop&#39;s connection is already gone. → <a href="./agents#ctrl-c-stops-the-work">Agents: Ctrl-C</a></p><h2 id="what-happens-when-something-dies" tabindex="-1">What happens when something dies <a class="header-anchor" href="#what-happens-when-something-dies" aria-label="Permalink to &quot;What happens when something dies&quot;">​</a></h2><table tabindex="0"><thead><tr><th>what dies</th><th>what happens</th></tr></thead><tbody><tr><td>your laptop sleeps, the network drops</td><td>the work goes on; <code>errand attach</code> picks it up</td></tr><tr><td>the errand command you typed</td><td>its agent stops what it started (unless it was <code>--batch</code>)</td></tr><tr><td>an agent, by SIGTERM or a logout</td><td>it stops what it runs before it goes</td></tr><tr><td>an agent, by SIGKILL or the OOM killer</td><td>the next agent on that machine finds what it left and kills it</td></tr><tr><td>a VM&#39;s keeper</td><td>QEMU goes with it</td></tr><tr><td>the command waiting for a Slurm job</td><td>the job is cancelled; an allocation kept warm ends on its own once unused</td></tr></tbody></table><p>That is the rule behind the whole part: <strong>nothing errand starts runs without someone on that machine keeping track of it.</strong> The design is in <a href="https://github.com/hleclerc/errand/blob/main/docs/adr/0008-nothing-runs-unowned.md" target="_blank" rel="noreferrer">ADR 0008</a> and <a href="https://github.com/hleclerc/errand/blob/main/docs/adr/0009-arrivals.md" target="_blank" rel="noreferrer">ADR 0009</a>.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p><a href="./agents">Agents and keeping warm</a> · <a href="./machine">Sharing a machine</a> · <a href="./layers/slurm">Slurm allocations</a> · <a href="./layers/windows">Windows VMs</a></p>`,26)])])}const k=t(i,[["render",o]]);export{g as __pageData,k as default};
